package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0) // PIC 9(8)V99 len=10 = 0
var WsCount int64 = 0 // PIC 9(3) len=3 = 0
var WsPriceEd string // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string  // PIC ZZ,ZZ9.99 len=9
var WsNetEd string   // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var discLines []string
var discIdx int
var discRec DiscRec

func parsePic9V99(s string) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64 = 0
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -2)
}

func parsePic92(s string) int64 {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64 = 0
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return n
}

func storeRounded(v decimal.Decimal, intDigits int) decimal.Decimal {
	r := v.Round(2)
	scaled := r.Shift(2).IntPart()
	var m int64 = 1
	for i := 0; i < intDigits+2; i++ {
		m *= 10
	}
	scaledMod := scaled % m
	return decimal.New(scaledMod, -2)
}

func storeTruncated(v decimal.Decimal, intDigits int) decimal.Decimal {
	r := v.Truncate(2)
	scaled := r.Shift(2).IntPart()
	var m int64 = 1
	for i := 0; i < intDigits+2; i++ {
		m *= 10
	}
	scaledMod := scaled % m
	return decimal.New(scaledMod, -2)
}

func formatEdited(v decimal.Decimal, pic string) string {
	dot := strings.Index(pic, ".")
	var leftPic string
	var decSlots int
	if dot >= 0 {
		leftPic = pic[:dot]
		rightPic := pic[dot+1:]
		decSlots = 0
		for _, c := range rightPic {
			if c == 'Z' || c == '9' {
				decSlots++
			}
		}
	} else {
		leftPic = pic
		decSlots = 0
	}
	intSlots := 0
	for _, c := range leftPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	q := v.Truncate(int32(decSlots))
	absQ := q.Abs()
	scaled := absQ.Shift(int32(decSlots)).IntPart()
	var powDec int64 = 1
	for i := 0; i < decSlots; i++ {
		powDec *= 10
	}
	var integerPart int64
	var fracPart int64
	if decSlots > 0 {
		integerPart = scaled / powDec
		fracPart = scaled % powDec
	} else {
		integerPart = scaled
		fracPart = 0
	}
	var powInt int64 = 1
	for i := 0; i < intSlots; i++ {
		powInt *= 10
	}
	if powInt != 0 {
		integerPart = integerPart % powInt
	}
	digits := make([]int, intSlots)
	tmp := integerPart
	for i := intSlots - 1; i >= 0; i-- {
		digits[i] = int(tmp % 10)
		tmp /= 10
	}
	firstNZ := intSlots
	for i := 0; i < intSlots; i++ {
		if digits[i] != 0 {
			firstNZ = i
			break
		}
	}
	var buf strings.Builder
	digitIdx := 0
	for _, c := range leftPic {
		switch c {
		case ',':
			if firstNZ >= digitIdx {
				buf.WriteByte(' ')
			} else {
				buf.WriteByte(',')
			}
		case 'Z', '9':
			d := digits[digitIdx]
			if c == '9' {
				buf.WriteByte(byte('0' + d))
			} else {
				if digitIdx < firstNZ {
					buf.WriteByte(' ')
				} else {
					buf.WriteByte(byte('0' + d))
				}
			}
			digitIdx++
		default:
			buf.WriteByte(byte(c))
		}
	}
	leftStr := buf.String()
	if dot >= 0 {
		fracStr := fmt.Sprintf("%0*d", decSlots, fracPart)
		return leftStr + "." + fracStr
	}
	return leftStr
}

func MainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if len(data) == 0 {
		discLines = []string{}
	} else {
		s := string(data)
		parts := strings.Split(s, "\n")
		if strings.HasSuffix(s, "\n") {
			parts = parts[:len(parts)-1]
		}
		discLines = make([]string, len(parts))
		for i, p := range parts {
			if len(p) > 0 && p[len(p)-1] == '\r' {
				p = p[:len(p)-1]
			}
			discLines[i] = p
		}
	}
	discIdx = 0
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if discIdx < len(discLines) {
		line := discLines[discIdx]
		discIdx++
		if len(line) < 15 {
			line += strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		discRec.DrItem = line[0:6]
		discRec.DrPrice = parsePic9V99(line[6:13])
		discRec.DrPct = parsePic92(line[13:15])
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	exactDisc := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	WsDiscount = storeRounded(exactDisc, 5)
	exactNet := discRec.DrPrice.Sub(WsDiscount)
	WsNet = storeTruncated(exactNet, 5)
	WsTotalNet = storeTruncated(WsTotalNet.Add(WsNet), 8)
	WsCount = (WsCount + 1) % 1000
	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")
	pctVal := discRec.DrPct % 100
	if pctVal < 0 {
		pctVal += 100
	}
	pctStr := fmt.Sprintf("%02d", pctVal)
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, pctStr, WsDiscEd, WsNetEd)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	MainPara()
}
